    'Price: low to high': { es: 'Precio: de menor a mayor', fr: 'Prix : croissant', pt: 'Preço: menor para maior', de: 'Preis: aufsteigend', it: 'Prezzo: crescente', ja: '価格：安い順', ko: '가격: 낮은 순', zh: '价格：从低到高' },
