    'Colours from the cars.': { es: 'Colores de los coches.', fr: 'Les couleurs des voitures.', pt: 'Cores dos carros.', de: 'Farben von den Autos.', it: 'Colori dalle auto.', ja: '色はクルマから。', ko: '컬러는 차에서.', zh: '颜色取自车身。' },
    'Colourways are pulled from each story’s colour guide.': { es: 'Los colores salen de la guía de color de cada historia.', fr: 'Les coloris sont tirés du nuancier de chaque récit.', pt: 'As cores saem do guia de cores de cada história.', de: 'Die Farbvarianten stammen aus dem Farbguide jeder Story.', it: 'Le colorazioni vengono dalla guida colori di ogni storia.', ja: 'カラーウェイは各ストーリーのカラーガイドから。', ko: '컬러웨이는 각 스토리의 컬러 가이드에서 가져와요.', zh: '配色取自每篇故事的配色指南。' },
    'Films.': { es: 'Películas.', fr: 'Films.', pt: 'Filmes.', de: 'Filme.', it: 'Film.', ja: 'フィルム。', ko: '필름.', zh: '影片。' },
    '4K director’s cuts as downloads.': { es: 'Director’s cuts en 4K para descargar.', fr: 'Director’s cuts 4K à télécharger.', pt: 'Director’s cuts em 4K para baixar.', de: '4K-Director’s-Cuts als Download.', it: 'Director’s cut in 4K da scaricare.', ja: '4Kディレクターズカットをダウンロードで。', ko: '4K 감독판 다운로드.', zh: '4K 导演剪辑版下载。' },
    'The exact grades, as .cube files for Resolve, Premiere, FCP and Lightroom.': { es: 'El etalonaje exacto, en archivos .cube para Resolve, Premiere, FCP y Lightroom.', fr: 'L’étalonnage exact, en fichiers .cube pour Resolve, Premiere, FCP et Lightroom.', pt: 'A cor exata, em arquivos .cube para Resolve, Premiere, FCP e Lightroom.', de: 'Das exakte Grading als .cube-Dateien für Resolve, Premiere, FCP und Lightroom.', it: 'Il grading esatto, in file .cube per Resolve, Premiere, FCP e Lightroom.', ja: 'グレーディングをそのまま、Resolve・Premiere・FCP・Lightroom用の.cubeファイルで。', ko: '그레이딩 그대로, Resolve, Premiere, FCP, Lightroom용 .cube 파일로.', zh: '原版调色，提供适用于 Resolve、Premiere、FCP 和 Lightroom 的 .cube 文件。' },
    'Shipping.': { es: 'Envíos.', fr: 'Livraison.', pt: 'Envio.', de: 'Versand.', it: 'Spedizioni.', ja: '配送。', ko: '배송.', zh: '配送。' },
    'Apparel, skate and accessories ship from the KIOSK store. Shipping + returns →': { es: 'La ropa, el skate y los accesorios se envían desde la tienda KIOSK. Envíos + devoluciones →', fr: 'Vêtements, skate et accessoires sont expédiés depuis la boutique KIOSK. Livraison + retours →', pt: 'Roupas, skate e acessórios saem da loja KIOSK. Envio + devoluções →', de: 'Kleidung, Skate und Accessoires werden vom KIOSK Store verschickt. Versand + Rückgabe →', it: 'Abbigliamento, skate e accessori partono dal negozio KIOSK. Spedizioni + resi →', ja: 'アパレル、スケート、アクセサリーはKIOSKストアから発送。配送 + 返品 →', ko: '의류, 스케이트, 액세서리는 KIOSK 스토어에서 발송돼요. 배송 + 반품 →', zh: '服饰、滑板和配饰由 KIOSK 商店发货。配送 + 退货 →' },
    'Your store here': { es: 'Tu tienda aquí', fr: 'Ta boutique ici', pt: 'Sua loja aqui', de: 'Dein Store hier', it: 'Il tuo negozio qui', ja: 'あなたのストアをここに', ko: '여기에 당신의 스토어를', zh: '你的店铺在这里' },
    'Thrift curators, independent labels, makers anywhere in the world.': { es: 'Curadores de segunda mano, marcas independientes y creadores de todo el mundo.', fr: 'Curateurs de seconde main, labels indépendants, créateurs du monde entier.', pt: 'Curadores de brechó, marcas independentes, criadores de qualquer lugar do mundo.', de: 'Vintage-Kuratoren, unabhängige Labels, Maker überall auf der Welt.', it: 'Curatori vintage, label indipendenti, maker da tutto il mondo.', ja: '古着キュレーター、インディペンデントレーベル、世界中の作り手。', ko: '빈티지 큐레이터, 독립 레이블, 전 세계의 메이커.', zh: '古着买手、独立品牌，以及世界各地的创作者。' },
    'Get the stockist pack': { es: 'Recibe el kit para vendedores', fr: 'Recevoir le kit revendeur', pt: 'Receba o kit para lojistas', de: 'Händlerpaket anfordern', it: 'Ricevi il kit rivenditori', ja: '出店ガイドを受け取る', ko: '입점 안내 받기', zh: '获取入驻资料包' },

