    'Concourse · Partner stores': { es: 'Vestíbulo · Tiendas asociadas', fr: 'Hall · Boutiques partenaires', pt: 'Saguão · Lojas parceiras', de: 'Concourse · Partner-Stores', it: 'Concourse · Negozi partner', ja: 'コンコース · パートナーストア', ko: '콘코스 · 파트너 스토어', zh: '候机大厅 · 合作店铺' },
