    'Colourways come from each story’s colour guide.': { es: 'Los colores salen de la guía de color de cada historia.', fr: 'Les coloris viennent du nuancier de chaque récit.', pt: 'As cores vêm do guia de cores de cada história.', de: 'Die Farbvarianten stammen aus dem Farbguide jeder Story.', it: 'Le colorazioni vengono dalla guida colori di ogni storia.', ja: 'カラーウェイは各ストーリーのカラーガイドから。', ko: '컬러웨이는 각 스토리의 컬러 가이드에서 가져와요.', zh: '配色取自每个故事的色彩指南。' },
    'Checkout with Shopify.': { es: 'Pago con Shopify.', fr: 'Paiement via Shopify.', pt: 'Checkout com Shopify.', de: 'Checkout mit Shopify.', it: 'Pagamento con Shopify.', ja: 'Shopifyで決済。', ko: 'Shopify로 결제.', zh: '通过 Shopify 结账。' },
    'Secure checkout; partner pieces ship from their store.': { es: 'Pago seguro; las piezas de tiendas asociadas se envían desde su tienda.', fr: 'Paiement sécurisé ; les pièces partenaires sont expédiées depuis leur boutique.', pt: 'Pagamento seguro; as peças de parceiros são enviadas pela própria loja.', de: 'Sicherer Checkout; Partner-Teile werden vom jeweiligen Store verschickt.', it: 'Pagamento sicuro; i pezzi dei partner partono dal loro negozio.', ja: '安全な決済。パートナーのアイテムは各ストアから発送されます。', ko: '안전한 결제. 파트너 아이템은 해당 스토어에서 배송돼요.', zh: '安全结账；合作店铺的单品由其店铺发货。' },
    'Downloads.': { es: 'Descargas.', fr: 'Téléchargements.', pt: 'Downloads.', de: 'Downloads.', it: 'Download.', ja: 'ダウンロード。', ko: '다운로드.', zh: '下载。' },
    'Films and LUT packs arrive by email after purchase.': { es: 'Las películas y los packs de LUT llegan por email tras la compra.', fr: 'Films et packs de LUTs arrivent par e-mail après l’achat.', pt: 'Filmes e packs de LUT chegam por e-mail após a compra.', de: 'Filme und LUT-Packs kommen nach dem Kauf per E-Mail.', it: 'Film e pack di LUT arrivano via email dopo l’acquisto.', ja: 'フィルムとLUTパックは購入後にメールで届きます。', ko: '필름과 LUT 팩은 구매 후 이메일로 도착해요.', zh: '影片和 LUT 包会在购买后通过邮件发送。' },
    'Shipping + returns.': { es: 'Envíos + devoluciones.', fr: 'Livraison + retours.', pt: 'Envio + devoluções.', de: 'Versand + Rückgabe.', it: 'Spedizioni + resi.', ja: '配送と返品。', ko: '배송 + 반품.', zh: '配送与退货。' },
